#include <locale>
#include <sstream>
#include <iomanip>
#include <codecvt>
#include <string>
#include <cassert>
#include <type_traits>
#include <utility>
struct Marker : std::locale::facet {
    static std::locale::id id;
    Marker() : std::locale::facet(0u) {}
};
std::locale::id Marker::id;
int main() {
    std::locale classic = std::locale::classic(), copy;
    copy = classic;
    assert(copy == classic);
    auto previous = std::locale::global(classic);
    std::locale::global(previous);
    const auto &ctype = std::use_facet<std::ctype<char>>(classic);
    assert(ctype.is(std::ctype_base::alpha, 'A') && ctype.table() &&
        std::ctype<char>::classic_table());
    const auto &numbers = std::use_facet<std::numpunct<char>>(classic);
    assert(numbers.decimal_point() == '.');
    // Explicitly construct facets; their locale owns and destroys them.
    std::locale facets{classic, new std::ctype<char>};
    facets = std::locale{facets, new std::ctype<wchar_t>};
    facets = std::locale{facets, new std::collate<char>};
    facets = std::locale{facets, new std::codecvt<wchar_t, char, std::mbstate_t>};
    facets = std::locale{facets, new std::num_get<char>};
    facets = std::locale{facets, new std::num_put<char>};
    facets = std::locale{facets, new std::money_get<char>};
    facets = std::locale{facets, new std::money_put<char>};
    facets = std::locale{facets, new std::moneypunct<char>};
    facets = std::locale{facets, new std::messages<char>};
    facets = std::locale{facets, new std::time_get_byname<char>("C")};
    facets = std::locale{facets, new std::time_put<char>};
    std::locale named{classic, new std::collate_byname<char>("C")};
    assert(std::use_facet<std::collate<char>>(named).compare(
               "a", "a" + 1, "b", "b" + 1) < 0);
    const auto &codec =
        std::use_facet<std::codecvt<wchar_t, char, std::mbstate_t>>(classic);
    std::mbstate_t state{};
    char output[16], *next{};
    auto result = codec.unshift(state, output, output + 16, next);
    assert(result == std::codecvt_base::noconv || result == std::codecvt_base::ok);
    std::wstring_convert<std::codecvt_utf8<wchar_t>> convert;
    assert(convert.from_bytes("A") == L"A");
    (void)convert.state();
    std::stringbuf bytes;
    std::wbuffer_convert<std::codecvt_utf8<wchar_t>> buffer{&bytes};
    (void)buffer.state();
    std::locale custom{classic, new Marker};
    assert(std::has_facet<Marker>(custom));
    std::istringstream input{"123"};
    input.imbue(classic);
    int number{};
    input >> number;
    assert(number == 123);
    std::ostringstream text;
    text.imbue(classic);
    text << std::put_money(123);
    assert(!text.str().empty());
    std::istringstream money{"123"};
    long double amount{};
    money >> std::get_money(amount);
    assert(!money.fail());
    std::tm date{};
    date.tm_year = 124;
    date.tm_mon = 2;
    date.tm_mday = 15;
    std::ostringstream time;
    time << std::put_time(&date, "%Y-%m-%d");
    assert(time.str() == "2024-03-15");
    std::istringstream calendar{"2024-03-15"};
    calendar >> std::get_time(&date, "%Y-%m-%d");
    assert(!calendar.fail());
    auto order = std::use_facet<std::time_get<char>>(classic).date_order();
    (void)order;
    const auto &messages = std::use_facet<std::messages<char>>(classic);
    std::messages_base::catalog catalog =
        messages.open("cpp-library-missing-catalog", classic);
    if (catalog >= 0)
        messages.close(catalog);
    std::money_base::pattern pattern =
        std::use_facet<std::moneypunct<char>>(classic).pos_format();
    (void)pattern;
    // Stream extraction/insertion dispatches to the installed num_get/num_put,
    // money_get/money_put, and time_get/time_put facets.
}
